<?php
namespace App\Domain\Articles; use App\Models\Article; use Illuminate\Support\Facades\DB; use Illuminate\Validation\ValidationException; final class ArticleRelationManager { public function sync(Article $article,array $articles,array $solutions,array $products,array $industries,array $capabilities,array $pages):void{if(in_array($article->id,$articles,true)){throw ValidationException::withMessages(['article_ids'=>'An article cannot relate to itself.']);}DB::transaction(function()use($article,$articles,$solutions,$products,$industries,$capabilities,$pages){foreach(['relatedArticles'=>$articles,'relatedSolutions'=>$solutions,'relatedProducts'=>$products,'relatedIndustries'=>$industries,'relatedCapabilities'=>$capabilities,'relatedPages'=>$pages] as $relation=>$ids){$article->{$relation}()->sync(collect($ids)->values()->mapWithKeys(fn($id,$order)=>[$id=>['display_order'=>$order]])->all());}});ArticleCache::forget($article->id);} }
